<script setup lang="ts">import {onMounted,ref} from 'vue';import {stage3Api} from '@/api/stage3';const channels=ref<any[]>([]),active=ref('ai'),range=ref('day'),data=ref<any>({items:[],source_warnings:[]}),loading=ref(false);async function load(){loading.value=true;try{data.value=await stage3Api.discover({channel:active.value,range:range.value,page:1,page_size:30})}finally{loading.value=false}}async function select(id:string){active.value=id;await load()}async function feedback(id:string,type:string){await stage3Api.feedback(id,type);await load()}onMounted(async()=>{channels.value=await stage3Api.channels();await load()})</script>
<template><main class="stage-page"><header class="page-head"><div><p>DISCOVER / REAL SIGNALS</p><h1>发现值得看的内容</h1><span>榜单规则公开，每条建议都说明为什么出现。</span></div><select v-model="range" @change="load"><option value="day">今日</option><option value="week">本周</option><option value="month">本月</option></select></header><nav class="channels"><button v-for="c in channels" :key="c.id" :class="{active:active===c.id}" @click="select(c.id)">{{c.name}}<i v-if="c.followed">已关注</i></button></nav><p class="rule">{{data.ranking_rule}}</p><section v-if="loading" class="empty">正在按真实信号重新排序…</section><section v-else-if="!data.items.length" class="empty"><strong>当前频道没有真实内容</strong><p>切换时间范围，或前往数据源中心同步。系统不会生成模拟推荐。</p></section><div v-else class="discover-list"><article v-for="item in data.items" :key="item.id"><div class="score">{{Math.round(item.score)}}</div><div><small>{{item.source.name}} · {{item.published_at?.slice(0,10)}}</small><h2>{{item.title}}</h2><p>{{item.summary||'原始来源未提供正文摘要'}}</p><div class="reasons"><span v-for="r in item.recommendation_reasons" :key="r.rule">{{r.label}}</span></div><footer><a :href="item.canonical_url" target="_blank">原文</a><button @click="stage3Api.favorite('content',item.id)">收藏</button><button @click="feedback(item.id,'seen')">已看过</button><button @click="feedback(item.id,'not_interested')">不感兴趣</button></footer></div></article></div></main></template><style scoped src="@/assets/styles/stage3.css"></style>
